param([ValidateSet('Before','V11Preserve','Preserve','VerifyPreserved','FinalPreservation','InspectLegacy','Provision','Test','Serve','Browser','Review','Extra','Seed')][string]$Action='Preserve',[ValidateSet('01','02','03','04','05','06','demo','v11-01','v11-02','v11-03','v11-04','v11-demo')][string]$Target='01')
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$private=Join-Path $root 'server/.local/simple-v1';$node=Join-Path $root 'tmp/w05/runtime/node_modules/node/bin/node.exe'
if($Target.StartsWith('v11-')){$private=Join-Path $root 'server/.local/simple-v11'}
$saved=@{};Get-ChildItem Env:|ForEach-Object{$saved[$_.Name]=$_.Value};$buffers=[Collections.Generic.List[IntPtr]]::new()
function Secret($secure){$buffer=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure);$buffers.Add($buffer);return [Runtime.InteropServices.Marshal]::PtrToStringBSTR($buffer)}
function Generate($name,$path){if(Test-Path -LiteralPath $path){throw 'Existing profile: preserve without reuse'};$bytes=[byte[]]::new(40);[Security.Cryptography.RandomNumberGenerator]::Fill($bytes);$secure=ConvertTo-SecureString ([Convert]::ToBase64String($bytes)) -AsPlainText -Force;[Array]::Clear($bytes,0,$bytes.Length);$credential=[PSCredential]::new($name,$secure);$credential|Export-Clixml -LiteralPath $path -NoClobber;return $credential}
Push-Location $root
try{
 if(-not(Test-Path -LiteralPath $private)){New-Item -ItemType Directory -Path $private|Out-Null;$acl=Get-Acl $private;$acl.SetAccessRuleProtection($true,$false);foreach($sid in @([Security.Principal.WindowsIdentity]::GetCurrent().User,[Security.Principal.SecurityIdentifier]::new('S-1-5-18'))){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($sid,'FullControl','ContainerInherit,ObjectInherit','None','Allow'))};Set-Acl -LiteralPath $private -AclObject $acl}
 if((Get-Item $private).Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'Private directory must not be a link'}
 $ownerConfig=Get-Content server/.local/p21a/owner.connection.json -Raw|ConvertFrom-Json;if($ownerConfig.host -ne '127.0.0.1' -or $ownerConfig.port -ne 3309){throw 'Owner endpoint mismatch'}
 $owner=Import-Clixml server/.local/p21a/owner.credential.clixml;$env:DB_HOST='127.0.0.1';$env:DB_PORT='3309';$env:DB_NAME='upms';$env:DB_CONFIRM_NAME='upms';$env:DB_USER=$owner.UserName;$env:DB_PASSWORD=Secret $owner.Password;$env:DB_ALLOW_MARIADB_COMPATIBILITY='true';$env:IDENTITY_DB_PURPOSE='operator';$env:NODE_ENV='development';Remove-Item Env:UPMS_SIMPLE_V1 -ErrorAction SilentlyContinue
 if($Action -eq 'V11Preserve'){& $node server/tools/simple-v1-operations.mjs v11-preserve}
 elseif($Action -eq 'Preserve'){& $node server/tools/simple-v1-operations.mjs preserve}
 elseif($Action -eq 'FinalPreservation'){& $node server/tools/simple-v1-operations.mjs verify-final}
 elseif($Action -eq 'InspectLegacy'){& $node server/tools/simple-v1-operations.mjs inspect-legacy}
 elseif($Action -eq 'VerifyPreserved'){& $node server/tools/simple-v1-operations.mjs verify-preserved}
 elseif($Action -eq 'Provision'){
  $migration=Generate ($(if($Target.StartsWith('v11-')){'upms_migrator_v11_'+$Target.Substring(4)}else{'upms_migrator_test_simplev1_'+$Target})) (Join-Path $private "$Target-migrator.credential.clixml");$runtime=Generate ($(if($Target.StartsWith('v11-')){'upms_runtime_v11_'+$Target.Substring(4)}else{'upms_runtime_test_simplev1_'+$Target})) (Join-Path $private "$Target-runtime.credential.clixml");$operator=Generate 'v1_operator' (Join-Path $private "$Target-operator.credential.clixml");$session=Generate 'v1_session' (Join-Path $private "$Target-session.credential.clixml");$env:V1_MIGRATOR_PASSWORD=Secret $migration.Password;$env:V1_RUNTIME_PASSWORD=Secret $runtime.Password;$env:V1_OPERATOR_PASSWORD=Secret $operator.Password;& $node server/tools/simple-v1-operations.mjs provision $Target
 }else{
  $meta=Get-Content (Join-Path $private "$Target-provisioned.json") -Raw|ConvertFrom-Json;$runtime=Import-Clixml (Join-Path $private "$Target-runtime.credential.clixml");if($runtime.UserName -ne $meta.user){throw 'Runtime profile mismatch'};$env:DB_NAME=$meta.schema;$env:DB_CONFIRM_NAME=$meta.schema;$env:DB_USER=$runtime.UserName;$env:DB_PASSWORD=Secret $runtime.Password;$env:IDENTITY_DB_PURPOSE='runtime';$env:UPMS_SIMPLE_V1='synthetic-v1';$operator=Import-Clixml (Join-Path $private "$Target-operator.credential.clixml");$env:V1_OPERATOR_PASSWORD=Secret $operator.Password;$session=Import-Clixml (Join-Path $private "$Target-session.credential.clixml");$env:SESSION_SECRET=Secret $session.Password;$env:MANAGEMENT_ENABLED='true';$env:MANAGEMENT_LOCAL_HTTP='true';$env:MANAGEMENT_ORIGIN='http://127.0.0.1:3110';$env:PORT='3110';if($Target -eq 'v11-demo'){$env:MANAGEMENT_ORIGIN='http://127.0.0.1:3111';$env:PORT='3111'};$env:V1_TARGET=$Target
  if($Action -eq 'Before'){& $node server/tools/simple-v11-before.mjs}
  elseif($Action -eq 'Test'){if(Test-Path (Join-Path $private "$Target-started.json")){throw 'Never rerun a populated integration target'};@{started=[DateTime]::UtcNow.ToString('o');schema=$meta.schema}|ConvertTo-Json|Set-Content (Join-Path $private "$Target-started.json");& $node --test server/tests/mysql/simple-v1.integration.js}
  elseif($Action -eq 'Serve'){if($Target -eq 'v11-demo'){& $node server/tools/simple-v11-serve.mjs}else{& $node server/tools/simple-v1-serve.mjs}}
  else{if($Action -eq 'Review'){$env:V1_BROWSER_READONLY='true';& $node server/tools/simple-v1-demo.mjs browser}else{& $node server/tools/simple-v1-demo.mjs $Action.ToLower()}}
 }
 if($LASTEXITCODE -ne 0){throw 'V1 action stopped; retain all evidence and populated schemas'}
}finally{Pop-Location;foreach($buffer in $buffers){[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($buffer)};Get-ChildItem Env:|ForEach-Object{if(-not $saved.ContainsKey($_.Name)){[Environment]::SetEnvironmentVariable($_.Name,$null,'Process')}};foreach($name in $saved.Keys){[Environment]::SetEnvironmentVariable($name,$saved[$name],'Process')}}
